import re

_SIZES = {
    "char": 1, "bool": 1, "int8_t": 1, "uint8_t": 1,
    "short": 2, "int16_t": 2, "uint16_t": 2,
    "int": 4, "int32_t": 4, "uint32_t": 4, "float": 4,
    "long long": 8, "int64_t": 8, "uint64_t": 8, "double": 8, "pointer": 8,
}


def _size_align(c_type, pack):
    m = re.fullmatch(r"\s*(.+?)\s*\[\s*(\d+)\s*\]\s*", c_type)
    count = 1
    if m:
        c_type, count = m.group(1), int(m.group(2))
        if count < 1:
            raise ValueError(f"bad array length in {c_type!r}")
    c_type = " ".join(c_type.split())
    if c_type not in _SIZES:
        raise ValueError(f"unknown type: {c_type!r}")
    size = _SIZES[c_type]
    align = min(size, pack) if pack else size
    return size * count, align


def layout(fields, pack=None):
    offsets, end, struct_align = {}, 0, 1
    for name, c_type in fields:
        size, align = _size_align(c_type, pack)
        offset = (end + align - 1) // align * align
        offsets[name] = offset
        end = offset + size
        struct_align = max(struct_align, align)
    size = (end + struct_align - 1) // struct_align * struct_align
    return {"offsets": offsets, "size": size, "align": struct_align}

