import ctypes

CT = {"char": ctypes.c_char, "bool": ctypes.c_bool, "int8_t": ctypes.c_int8, "uint8_t": ctypes.c_uint8,
      "short": ctypes.c_short, "int16_t": ctypes.c_int16, "uint16_t": ctypes.c_uint16, "int": ctypes.c_int,
      "int32_t": ctypes.c_int32, "uint32_t": ctypes.c_uint32, "float": ctypes.c_float, "long long": ctypes.c_longlong,
      "int64_t": ctypes.c_int64, "uint64_t": ctypes.c_uint64, "double": ctypes.c_double, "pointer": ctypes.c_void_p}

def ctypes_layout(fields, pack=None):
    spec = []
    for name, t in fields:
        if "[" in t:
            base, n = t.split("[")
            spec.append((name, CT[base.strip()] * int(n.rstrip("] "))))
        else:
            spec.append((name, CT[t]))
    attrs = {"_fields_": spec}
    if pack:
        attrs["_pack_"] = pack
    S = type("S", (ctypes.Structure,), attrs)
    return {"offsets": {n: getattr(S, n).offset for n, _ in fields}, "size": ctypes.sizeof(S), "align": ctypes.alignment(S)}

CASES = [
    [("x", "int"), ("y", "double")],
    [("a", "char"), ("b", "int"), ("c", "char")],
    [("a", "char"), ("b", "char"), ("c", "short"), ("d", "int")],
    [("flag", "bool"), ("name", "char[13]"), ("value", "double"), ("count", "uint16_t")],
    [("p", "pointer"), ("tag", "uint8_t"), ("ids", "int32_t[3]")],
    [("only", "short")],
]

@test("simple cases worked by hand")
def _():
    check_eq(layout([("x", "int"), ("y", "double")]), {"offsets": {"x": 0, "y": 8}, "size": 16, "align": 8})
    check_eq(layout([("a", "char"), ("b", "int"), ("c", "char")]), {"offsets": {"a": 0, "b": 4, "c": 8}, "size": 12, "align": 4})
    check_eq(layout([]), {"offsets": {}, "size": 0, "align": 1})

@test("the same as ctypes")
def _():
    for fields in CASES:
        check_eq(layout(fields), ctypes_layout(fields))

@test("packed structures")
def _():
    check_eq(layout([("a", "char"), ("b", "int"), ("c", "char")], pack=1), {"offsets": {"a": 0, "b": 1, "c": 5}, "size": 6, "align": 1})
    for fields in CASES:
        for pack in (1, 2, 4):
            check_eq(layout(fields, pack=pack), ctypes_layout(fields, pack=pack))

@test("bad types")
def _():
    check_raises(ValueError, layout, [("x", "long")])
    check_raises(ValueError, layout, [("x", "int[0]")])
    check_raises(ValueError, layout, [("x", "string")])

